command:
$ErrorActionPreference = "Stop"
git fetch origin main work/direct-shell-context-column-resize --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "d50f01e8ccecb800f0dbac6c0b9f550e9cb25e49") { throw "main moved" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }
git checkout -B work/direct-shell-context-column-resize origin/work/direct-shell-context-column-resize
if ($LASTEXITCODE -ne 0) { throw "checkout candidate failed" }
if ((git rev-parse HEAD).Trim() -ne "149d54a125570aa8014d26ef00952c37be37d15a") { throw "candidate mismatch" }

cmd /c test.bat source
if ($LASTEXITCODE -ne 0) { throw "source contracts failed" }

cmd /c build.bat Release
if ($LASTEXITCODE -ne 0) { throw "Release build failed" }

python -X utf8 tests\winui\test_owned_context_menu_gui.py Release
if ($LASTEXITCODE -ne 0) { throw "direct Shell context-menu GUI acceptance failed" }

python -X utf8 tests\winui\test_owned_column_resize_gui.py Release
if ($LASTEXITCODE -ne 0) { throw "Details column resize GUI acceptance failed" }

$source = "C:\dev\flyExplorer\logs\m24"
$target = "C:\dev\flyExplorer\logs\remote-evidence"
$files = @(
  "direct-shell-context-after.png",
  "detail-columns-before.png",
  "detail-columns-after.png"
)
New-Item -ItemType Directory -Force -Path $target | Out-Null
Get-ChildItem -LiteralPath $target -File -ErrorAction SilentlyContinue | Remove-Item -Force
foreach ($name in $files) {
  $path = Join-Path $source $name
  if (!(Test-Path -LiteralPath $path -PathType Leaf)) { throw "visual evidence missing: $name" }
  Copy-Item -LiteralPath $path -Destination (Join-Path $target $name)
}
Get-FileHash -Algorithm SHA256 -LiteralPath ($files | ForEach-Object { Join-Path $source $_ }) |
  ForEach-Object { "$($_.Path) $($_.Hash)" } |
  Set-Content -Encoding UTF8 -LiteralPath (Join-Path $target "direct-shell-column-sha256.txt")

git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }
Write-Host "DIRECT_SHELL_CONTEXT_COLUMN_RESIZE_ACCEPTANCE_PASS"
